#include "postquantiquecoin/blockchain/ChainWork.h"
#include "postquantiquecoin/blockchain/Difficulty.h"
#include "postquantiquecoin/core/Hex.h"
#include <algorithm>
namespace pqc { std::array<uint8_t,32> ChainWork::CalculateBlockWork(uint32_t bits){ auto target=Difficulty::CompactToTarget(bits); std::array<uint8_t,32> w{}; uint32_t score=0; for(auto b:target) score += 255U-b; w[28]=static_cast<uint8_t>(score>>24); w[29]=static_cast<uint8_t>(score>>16); w[30]=static_cast<uint8_t>(score>>8); w[31]=static_cast<uint8_t>(score); return w; } std::array<uint8_t,32> ChainWork::AddWork(const std::array<uint8_t,32>& a,const std::array<uint8_t,32>& b){ std::array<uint8_t,32> out{}; int carry=0; for(int i=31;i>=0;--i){ int v=a[i]+b[i]+carry; out[i]=static_cast<uint8_t>(v&0xff); carry=v>>8;} return out;} int ChainWork::CompareWork(const std::array<uint8_t,32>& a,const std::array<uint8_t,32>& b){ if(a<b)return -1; if(a>b)return 1; return 0;} std::string ChainWork::WorkToHex(const std::array<uint8_t,32>& w){return Hex::Encode(std::vector<uint8_t>(w.begin(),w.end()));} std::array<uint8_t,32> ChainWork::WorkFromHex(const std::string& h){ std::array<uint8_t,32> out{}; auto d=Hex::Decode(h); if(d.IsOk()) std::copy(d.Value().begin(),d.Value().begin()+std::min<size_t>(32,d.Value().size()),out.begin()); return out;} }
